/* live-nba.js — HAND-BUILT read-only client for ESPN's public NBA core API.
 *
 * Status: MAPPING ONLY. Not wired into live.html. No PR. No build step.
 * This file was hand-written (not generated by reverse-api-engineer — no
 * SDK key is configured on this VM) against live endpoint responses
 * captured 2026-10-21. Every endpoint below is public, no-auth, read-only.
 *
 * What works: game list, live scores, clock/period, pregame + live win
 * probability (ESPN BPI), schedules.
 * What does NOT work: shot-chart DATA (only an availability flag exists
 * publicly — the page's "shot charts" promise cannot be wired to live data).
 *
 * Refresh guidance: 30s while any game is live, 5 min otherwise.
 * On any fetch failure: surface "unavailable", never a stale number.
 */
(function () {
  "use strict";

  var BASE = "https://sports.core.api.espn.com/v2/sports/basketball/leagues/nba";
  var QS = "?lang=en&region=us";

  /* Static 30-team map (id -> abbr/name/colors), captured 2026-10-21.
   * Ships inline so the client never fetches team metadata. */
  var TEAMS = {
    "1":  { "abbr": "ATL", "name": "Atlanta Hawks", "color": "e31837", "alt": "c3d600" },
    "2":  { "abbr": "BOS", "name": "Boston Celtics", "color": "007a33", "alt": "ffffff" },
    "3":  { "abbr": "NO", "name": "New Orleans Pelicans", "color": "0c2340", "alt": "c8102e" },
    "4":  { "abbr": "CHI", "name": "Chicago Bulls", "color": "ce1141", "alt": "000000" },
    "5":  { "abbr": "CLE", "name": "Cleveland Cavaliers", "color": "860038", "alt": "fdbb30" },
    "6":  { "abbr": "DAL", "name": "Dallas Mavericks", "color": "00538c", "alt": "002b5e" },
    "7":  { "abbr": "DEN", "name": "Denver Nuggets", "color": "0e2240", "alt": "fec524" },
    "8":  { "abbr": "DET", "name": "Detroit Pistons", "color": "c8102e", "alt": "1d42ba" },
    "9":  { "abbr": "GS", "name": "Golden State Warriors", "color": "1d428a", "alt": "ffc72c" },
    "10": { "abbr": "HOU", "name": "Houston Rockets", "color": "ce1141", "alt": "000000" },
    "11": { "abbr": "IND", "name": "Indiana Pacers", "color": "002d62", "alt": "fdbb30" },
    "12": { "abbr": "LAC", "name": "LA Clippers", "color": "c8102e", "alt": "1d428a" },
    "13": { "abbr": "LAL", "name": "Los Angeles Lakers", "color": "552583", "alt": "fdb927" },
    "14": { "abbr": "MIA", "name": "Miami Heat", "color": "98002e", "alt": "f9a01b" },
    "15": { "abbr": "MIL", "name": "Milwaukee Bucks", "color": "00471b", "alt": "eee1c6" },
    "16": { "abbr": "MIN", "name": "Minnesota Timberwolves", "color": "0c2340", "alt": "236192" },
    "17": { "abbr": "BKN", "name": "Brooklyn Nets", "color": "000000", "alt": "ffffff" },
    "18": { "abbr": "NY", "name": "New York Knicks", "color": "006bb6", "alt": "f58426" },
    "19": { "abbr": "ORL", "name": "Orlando Magic", "color": "0150b5", "alt": "9ca0a3" },
    "20": { "abbr": "PHI", "name": "Philadelphia 76ers", "color": "006bb6", "alt": "ed174c" },
    "21": { "abbr": "PHX", "name": "Phoenix Suns", "color": "1d1160", "alt": "e56020" },
    "22": { "abbr": "POR", "name": "Portland Trail Blazers", "color": "e03a3e", "alt": "000000" },
    "23": { "abbr": "SAC", "name": "Sacramento Kings", "color": "5a2d81", "alt": "63727a" },
    "24": { "abbr": "SA", "name": "San Antonio Spurs", "color": "8a8d8f", "alt": "000000" },
    "25": { "abbr": "OKC", "name": "Oklahoma City Thunder", "color": "007ac1", "alt": "ef3b24" },
    "26": { "abbr": "UTAH", "name": "Utah Jazz", "color": "002b5c", "alt": "00471b" },
    "27": { "abbr": "WSH", "name": "Washington Wizards", "color": "002b5c", "alt": "e31837" },
    "28": { "abbr": "TOR", "name": "Toronto Raptors", "color": "ce1141", "alt": "000000" },
    "29": { "abbr": "MEM", "name": "Memphis Grizzlies", "color": "5d76a9", "alt": "12173f" },
    "30": { "abbr": "CHA", "name": "Charlotte Hornets", "color": "1d1160", "alt": "00788c" }
  };

  function get(url) {
    return fetch(url, { headers: { "Accept": "application/json" } }).then(function (r) {
      if (!r.ok) throw new Error("HTTP " + r.status + " for " + url);
      return r.json();
    });
  }

  function eventIdFromRef(ref) {
    var m = /\/events\/(\d+)/.exec(ref || "");
    return m ? m[1] : null;
  }

  /* (1) Game list for a date. dateStr = "YYYYMMDD". */
  function fetchScoreboard(dateStr) {
    return get(BASE + "/events?dates=" + dateStr + "&lang=en&region=us").then(function (d) {
      return (d.items || []).map(function (it) {
        return eventIdFromRef(it.$ref);
      }).filter(Boolean);
    });
  }

  /* (2)+(3) One game's competition: teams, status ref, predictor ref.
   * Returns normalized game object; scores fetched in parallel. */
  function fetchGame(eventId) {
    var curl = BASE + "/events/" + eventId + "/competitions/" + eventId + QS;
    return get(curl).then(function (comp) {
      var competitors = comp.competitors || [];
      var home = competitors.filter(function (c) { return c.homeAway === "home"; })[0] || {};
      var away = competitors.filter(function (c) { return c.homeAway === "away"; })[0] || {};
      var teamId = function (c) {
        var m = /\/competitors\/(\d+)/.exec((c.$ref || ""));
        return m ? m[1] : null;
      };
      var hid = teamId(home), aid = teamId(away);
      return Promise.all([
        get(comp.status.$ref),
        home.score ? get(home.score.$ref) : Promise.resolve(null),
        away.score ? get(away.score.$ref) : Promise.resolve(null)
      ]).then(function (parts) {
        var status = parts[0], hs = parts[1], as = parts[2];
        var st = status.type || {};
        return {
          eventId: eventId,
          name: comp.name || "",
          date: comp.date || "",
          state: st.state || "pre",           // pre | in | post
          detail: st.shortDetail || "",
          clock: status.displayClock || "",
          period: status.period || 0,
          completed: !!st.completed,
          home: {
            id: hid, abbr: (TEAMS[hid] || {}).abbr || "?",
            name: (TEAMS[hid] || {}).name || "",
            score: hs ? hs.displayValue : null,
            winner: !!home.winner
          },
          away: {
            id: aid, abbr: (TEAMS[aid] || {}).abbr || "?",
            name: (TEAMS[aid] || {}).name || "",
            score: as ? as.displayValue : null,
            winner: !!away.winner
          },
          predictorRef: (comp.predictor || {}).$ref || null,
          shotChartAvailable: !!comp.shotChartAvailable, // flag only — no public data behind it
          _comp: comp
        };
      });
    });
  }

  /* (4) Win probability (ESPN BPI). Returns {awayPct, homePct, matchupQuality}
   * or null when unavailable. Away value is explicit; home is 100 - away. */
  function fetchWinProb(eventId) {
    var purl = BASE + "/events/" + eventId + "/competitions/" + eventId + "/predictor" + QS;
    return get(purl).then(function (p) {
      var stats = ((p.awayTeam || {}).statistics || []);
      var gp = stats.filter(function (s) { return s.name === "gameProjection"; })[0];
      var mq = stats.filter(function (s) { return s.name === "matchupQuality"; })[0];
      if (!gp) return null;
      var awayPct = parseFloat(gp.displayValue);
      return {
        awayPct: awayPct,
        homePct: Math.round((100 - awayPct) * 10) / 10,
        matchupQuality: mq ? parseFloat(mq.displayValue) : null,
        asOf: p.lastModified || null,
        label: "ESPN BPI win probability"
      };
    }).catch(function () { return null; }); // win prob is nice-to-have; never break the page
  }

  /* Full refresh for a date: games with scores+status, in parallel. */
  function refresh(dateStr, withWinProb) {
    return fetchScoreboard(dateStr).then(function (ids) {
      return Promise.all(ids.map(function (id) {
        return fetchGame(id).then(function (g) {
          if (!withWinProb) return g;
          return fetchWinProb(id).then(function (w) { g.winProb = w; return g; });
        }).catch(function (err) {
          return { eventId: id, error: String(err && err.message || err), unavailable: true };
        });
      }));
    });
  }

  /* Suggested cadence: 30s while any game is live, 5 min otherwise. */
  function anyLive(games) {
    return games.some(function (g) { return g.state === "in"; });
  }

  window.LIVE_NBA = {
    TEAMS: TEAMS,
    fetchScoreboard: fetchScoreboard,
    fetchGame: fetchGame,
    fetchWinProb: fetchWinProb,
    refresh: refresh,
    anyLive: anyLive,
    HAND_BUILT: true
  };
})();
